// One item per storyboard page of each new request (reminders send no pages). The worker serves
// the pages against the episode_code job's board token (D-055). Replace the base URL on import.
// The video's own worker (D-074); WORKER is the fallback filled in on deploy.
const WORKER = 'REPLACE_WITH_WORKER_URL';
const rows = $input.all().filter((item) => item.json.kind === 'REQUEST' && item.json.board);
return rows.flatMap(({ json: row }) => {
  const board = typeof row.board === 'string' ? JSON.parse(row.board) : row.board;
  const shortId = String(row.video_id).slice(0, 8);
  return board.pages.map((page, i) => ({
    json: {
      url: `${row.worker_url || WORKER}/boards/${row.video_id}/${row.version}/${board.job_id}/${page.split('/').pop()}?t=${board.token}`,
      caption: `🎬 #${shortId} · ${i + 1}/${board.pages.length}`,
    },
  }));
});

// The episode's audio mix (voice + SFX, D-071) of each new request, after its pages; episode code
// written before the mix has none. Served against the episode_code job's media token.
// The video's own worker (D-074); WORKER is the fallback filled in on deploy.
const WORKER = 'REPLACE_WITH_WORKER_URL';
const parse = (value) => (typeof value === 'string' ? JSON.parse(value) : value);
const rows = $input.all().filter((item) => item.json.kind === 'REQUEST' && parse(item.json.board)?.mix_token);
return rows.map(({ json: row }) => {
  const board = parse(row.board);
  const shortId = String(row.video_id).slice(0, 8);
  return {
    json: {
      url: `${row.worker_url || WORKER}/media/${row.video_id}/${row.version}/${board.job_id}/mix.m4a?t=${board.mix_token}`,
      caption: `🎬 #${shortId} v${row.version} · âm thanh (giọng + SFX)`,
    },
  };
});

// One message with buttons per row from storyboard_approvals_due(), after its pages and mix
// (Vietnamese, D-061). Notes come back as a reply to this message (WF-06 finds the request by the
// hidden ref link). Callback data: sb:<A|F|R>:<32-hex token>; F is Render final (D-076): A2 and A3
// of this storyboard are then approved without buttons when their QA has no warnings.
// Shared Telegram formatting (same in every approval message node): the text goes out as HTML,
// times in Vietnam time (UTC+7, no daylight saving), and the request token rides in a hidden link
// at the start, so a reply to the message finds its request (WF-06) without showing the token.
const esc = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const vnTime = (value) => {
  const d = new Date(new Date(value).getTime() + 7 * 3_600_000);
  const p = (n) => String(n).padStart(2, '0');
  return `${p(d.getUTCHours())}:${p(d.getUTCMinutes())} ${p(d.getUTCDate())}/${p(d.getUTCMonth() + 1)}`;
};
const hiddenRef = (kind, token) => `<a href="https://t.me/?${kind}=${token}">\u200d</a>`;
const rows = $input.all().filter((item) => typeof item.json.token === 'string');
return rows.map(({ json: row }) => {
  const shortId = String(row.video_id).slice(0, 8);
  const reminder = row.kind === 'REMINDER';
  const html = [
    `${hiddenRef('ref', row.token)}<b>${reminder ? '⏰ Nhắc: ' : ''}🎬 Duyệt storyboard</b> · bước 3/5 · vòng ${row.round}/4`,
    `«${esc(row.title ?? '?')}»`,
    `#${shortId} v${row.version} · Render preview → gửi preview để duyệt`,
    'Render final → tự duyệt preview + metadata nếu QA không cảnh báo',
    `⏰ Hạn ${vnTime(row.expires_at)} · ↩️ Reply tin này để góp ý sửa`,
  ].join('\n');
  return { json: { html, approve: `sb:A:${row.token}`, approveAll: `sb:F:${row.token}`, reject: `sb:R:${row.token}` } };
});
